using System;using System.IO;using System.Diagnostics;using System.Threading;using System.Runtime.InteropServices;using System.Security.AccessControl;using System.Security.Principal;using System.Security.Cryptography;using System.Text;using System.Web.Script.Serialization;using System.Collections.Generic;using Enclave.OwnedRpc;
public static class NativeRpcProcessHarness {
 [DllImport("kernel32.dll")]static extern IntPtr GetCurrentProcess();[DllImport("kernel32.dll",SetLastError=true)]static extern bool TerminateProcess(IntPtr h,uint code);
 [DllImport("ntdll.dll")]static extern int NtQuerySystemInformation(int kind,out BootInfo value,int length,out int returned);
 [StructLayout(LayoutKind.Explicit,Size=32)]struct BootInfo{[FieldOffset(0)]public Guid Identifier;[FieldOffset(16)]public uint Firmware;[FieldOffset(24)]public ulong Flags;}
 static string Boot(){BootInfo b;int returned;Check(NtQuerySystemInformation(90,out b,32,out returned)==0&&returned==32&&b.Identifier!=Guid.Empty);return b.Identifier.ToString("N");}
 static long end;static Process node,blocked;static int output;static readonly object gate=new object();static JavaScriptSerializer J=new JavaScriptSerializer();
 static void Check(bool b){if(!b)throw new Exception("Fixture assertion");}static string Hash(byte[] b){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(b)).Replace("-","").ToLowerInvariant();}static string H(char c){return new string(c,64);}static string Q(string s){Check(s.IndexOfAny(new[]{'"','\r','\n'})<0);return "\""+s+"\"";}
 static void Dir(string p){var a=new DirectorySecurity();a.SetOwner(new SecurityIdentifier("S-1-5-32-544"));a.SetAccessRuleProtection(true,false);foreach(string sid in new[]{"S-1-5-18","S-1-5-32-544"})a.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid),FileSystemRights.FullControl,InheritanceFlags.ContainerInherit|InheritanceFlags.ObjectInherit,PropagationFlags.None,AccessControlType.Allow));Directory.CreateDirectory(p,a);}
 static void Put(string p,byte[] b){var a=new FileSecurity();a.SetOwner(new SecurityIdentifier("S-1-5-32-544"));a.SetAccessRuleProtection(true,false);foreach(string sid in new[]{"S-1-5-18","S-1-5-32-544"})a.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid),FileSystemRights.FullControl,AccessControlType.Allow));using(var f=new FileStream(p,FileMode.CreateNew,FileSystemRights.WriteData,FileShare.None,4096,FileOptions.WriteThrough,a)){f.Write(b,0,b.Length);f.Flush(true);}}
 static void Json(string p,object v){Put(p,Encoding.UTF8.GetBytes(J.Serialize(v)));}
 static void Line(object sender,DataReceivedEventArgs e){if(e.Data==null)return;lock(gate){output+=Encoding.UTF8.GetByteCount(e.Data)+2;if(output>65536){TerminateProcess(GetCurrentProcess(),126);return;}Console.WriteLine(e.Data);}}
 public static int Main(string[] args){long start=BoundedWorker.MonotonicMilliseconds();end=start+50000;try{
  var ack=new ManualResetEvent(false);var watchdog=new Thread(()=>{ack.Set();while(BoundedWorker.MonotonicMilliseconds()<end)Thread.Sleep(5);TerminateProcess(GetCurrentProcess(),124);});watchdog.IsBackground=true;watchdog.Start();Check(ack.WaitOne(1000));
  var envelope=BoundedWorker.EnterSupervisorEnvelope(256UL*1024*1024);Check(args.Length==3);string nodeExe=Path.GetFullPath(args[0]),script=Path.GetFullPath(args[1]),candidate=Path.GetFullPath(args[2]);byte[] image=File.ReadAllBytes(candidate);Check(image.Length==237568&&Hash(image)=="22e033958a4bbd695342b74248079ddf90b2788f1efe8f83def023710c4deb6f");
  string root=Path.Combine(Path.GetPathRoot(Environment.SystemDirectory),"rpc-process-ci-"+Guid.NewGuid().ToString("N"));Dir(root);string exe=Path.Combine(root,"controller.exe");Put(exe,image);
  foreach(string n in new[]{"manager","blocked"}){string dir=Path.Combine(root,n);Dir(dir);string ledger=Path.Combine(dir,"ledger"),attempts=Path.Combine(dir,"attempts"),workers=Path.Combine(dir,"workers");foreach(string d in new[]{ledger,attempts,workers,Path.Combine(ledger,"transport")})Dir(d);Put(Path.Combine(ledger,"manager.lock"),new byte[0]);byte[] inert=Encoding.UTF8.GetBytes("{\"fixture\":\"no target authority\"}");string admission=Path.Combine(dir,"admission.json");Put(admission,inert);
   Json(Path.Combine(dir,"config.json"),new{schema="native-rpc-manager-controller/1",ledgerRoot=ledger,attemptsRoot=attempts,workersRoot=workers,runtimeId=H('b'),profileSha256=H('d'),admissionSha256=Hash(inert),firmwareSha256=H('a'),initialStateSha256=H('a'),workerSha256=H('a'),admissionPath=admission,firmwarePath=Path.Combine(dir,"intentionally-absent.igvm"),initialStatePath=Path.Combine(dir,"absent.vmgs"),profilePath=Path.Combine(dir,"absent.profile"),workerPath=Path.Combine(dir,"absent-worker.exe")});
  }
  // Same native class/layout as maintained CurrentBoot; no clock is supplied.
  Json(Path.Combine(root,"fixture.json"),new{executable=exe,executableSha256=Hash(image),boot=Boot()});
  var psi=new ProcessStartInfo(nodeExe,"--max-old-space-size=64 "+Q(script)+" "+Q(root)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,WorkingDirectory=root};
  string systemRoot=Environment.GetEnvironmentVariable("SystemRoot"),temp=Environment.GetEnvironmentVariable("TEMP");psi.EnvironmentVariables.Clear();psi.EnvironmentVariables["SystemRoot"]=systemRoot;psi.EnvironmentVariables["TEMP"]=temp;psi.EnvironmentVariables["TMP"]=temp;
  node=new Process();node.StartInfo=psi;node.OutputDataReceived+=Line;node.ErrorDataReceived+=Line;Check(node.Start());IntPtr nh=node.Handle;long nc=node.StartTime.ToUniversalTime().ToFileTimeUtc();node.BeginOutputReadLine();node.BeginErrorReadLine();
  while(!node.WaitForExit(5)){if(blocked==null&&File.Exists(Path.Combine(root,"blocked.pid"))){string t=File.ReadAllText(Path.Combine(root,"blocked.pid"));if(t.Length==0)continue;int pid=Int32.Parse(t);blocked=Process.GetProcessById(pid);IntPtr bh=blocked.Handle;Check(!blocked.HasExited&&blocked.StartTime.ToUniversalTime().ToFileTimeUtc()>=nc&&String.Equals(blocked.MainModule.FileName,exe,StringComparison.OrdinalIgnoreCase));Console.WriteLine("HELD "+J.Serialize(new{pid=pid,creation=blocked.StartTime.ToUniversalTime().ToFileTimeUtc(),image=Hash(image)}));}Check(BoundedWorker.MonotonicMilliseconds()<end-1000);}
  node.WaitForExit();Check(node.ExitCode==0&&blocked!=null&&blocked.WaitForExit(0)&&blocked.ExitCode==125);
  Console.WriteLine("EXACT "+J.Serialize(new{nodePid=node.Id,nodeCreation=nc,nodeExit=node.ExitCode,blockedPid=blocked.Id,blockedCreation=blocked.StartTime.ToUniversalTime().ToFileTimeUtc(),blockedExit=blocked.ExitCode,elapsedMs=BoundedWorker.MonotonicMilliseconds()-start,jobBytes=envelope.JobCommitLimitBytes,member=envelope.MembershipVerified,limits=envelope.LimitsVerified,rpcReady=false}));return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{if(blocked!=null)blocked.Dispose();if(node!=null)node.Dispose();}}
}
